impl GpioLine {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"line\":");
		let _ = write!(out, "{}", self.line);
		out.push(',');
		out.push_str("\"name\":");
		crate::codec::json_escape(&self.name, out);
		out.push(',');
		out.push_str("\"trigger\":");
		self.trigger.to_json_into(out);
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("line=");
		let _ = write!(out, "{}", self.line);
		out.push_str(", ");
		out.push_str("name=");
		out.push_str(&self.name);
		out.push_str(", ");
		out.push_str("trigger=");
		self.trigger.to_text_into(out);
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 3);
		crate::codec::cbor::text(out, "line");
		crate::codec::cbor::uint(out, self.line as u64);
		crate::codec::cbor::text(out, "name");
		crate::codec::cbor::text(out, &self.name);
		crate::codec::cbor::text(out, "trigger");
		self.trigger.to_cbor_into(out);
	}
}

impl GpioEvent {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"level\":");
		if self.level {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"sequence\":");
		let _ = write!(out, "{}", self.sequence);
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("level=");
		if self.level {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("sequence=");
		let _ = write!(out, "{}", self.sequence);
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 2);
		crate::codec::cbor::text(out, "level");
		crate::codec::cbor::boolean(out, self.level);
		crate::codec::cbor::text(out, "sequence");
		crate::codec::cbor::uint(out, self.sequence as u64);
	}
}

